import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"5、【需】 乾下坎上","description":"周易口訣義 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"周易口訣義 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"classics/koujueyi/007.md","filePath":"classics/koujueyi/007.md"}'),r={name:"classics/koujueyi/007.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>彖曰：需，須也，險在前也。剛健而不陷，其義不困窮矣。「需，有孚，光亨，貞吉」，位乎天位，以正中也。「利涉大川」，往有功也。</p><p>象曰：雲上於天，需。君子以飲食宴樂。</p><p>初九：需於郊，利用恆，無咎。</p><p>象曰：「需於郊」，不犯難行也。「利用恆無咎」，未失常也。</p><p>九二，需於沙，小有言，終吉。</p><p>象曰：「需於沙」，衍在中也。雖小有言，以吉終也。</p><p>九三，雷於泥，致寇至。象曰：「需於泥」，災在外也。自我致寇，敬慎不敗也。</p><p>六四，需於血，出自穴。</p><p>象曰：「需於血」，順以聽也。</p><p>九五，需於酒食，貞吉。</p><p>象曰：酒食貞吉，以中正也。</p><p>上六，入於穴，有不速之客三人來，敬之終吉。</p><p>象曰：「不速之客來，敬之終吉」，雖不當位，未大失也。</p><p>解讀</p><p>「需有孚光亨貞吉」者，需，待也，乾健獲進，坎險在前，畏而不進，故稱待也。凡人待物，必須有信，信既立矣，即道德亨通，於正獲吉，故曰「光亨貞吉」也。「利涉大川」者，以信待物，又以「乾」之剛健，不患於險，故可濟涉大川，不憂沉溺也。</p><p>象曰「雲上於天，需，君子以飲食宴樂」者，「坎」為雲也，乾，天也，雲上於天，待時降雨，是需待之象也。君子當其時，待養而成，故王氏雲：「童蒙已發，盛德光亨，飲食宴樂，其在茲乎！」</p><p>「初九，需於郊，利用恆，無咎」者，爾雅雲：「邑外謂之郊也。」初九去難既遠，雖不應於幾速，但可以處於郊境之外，待時而已也。「利用恆，無咎」者，既不逼於險難，其所營為不失恆道，故不陷於咎也。</p><p>「九二，需於沙，小有言，終吉」，「沙」謂水之旁，去難漸近。既近於難，不能不有責讓之言。以其剛健，寬而處中，待時而進，雖有責讓之言，終保吉矣，故曰：「小有言，終吉」也。</p><p>「九三，需於泥，致寇至」者，九三已逼於難，故稱「泥」，「泥」謂險難也。「致寇至」者，招也。既逼險難，即是招致寇害，以相侵敵，然而不為遽進，猶有待焉，故不為困憊。</p><p>「六四，需於血，出自穴」者，血是陰陽相傷也。六四以陰柔之質，當剛健之路，乾剛既進，必見侵傷，故曰「需於血」。陽既強盛而前進，力不能敵，故以出於窟穴而避之，故曰「出自穴」也。</p><p>九五，需於酒食，貞吉者，人之所須，以求貴位，身既處於尊位而為天下所歸，即何更望求焉？但施酒食，暢其中情而已，故曰「需於酒食」也。然至飲食過節，患所生焉，故紂作靡靡之樂，天下為之離叛，必須飲食以宜，而不失貞正之道，可以獲吉，故曰「貞吉」也。</p><p>「上六：入於穴，有不速之客三人來，敬之，終吉」者，上六需難既終，不須出穴，安於舊位，故曰「入於穴」也。速，召也。三人，謂乾三陽也。言難道既終，三陽務進，不待上六召喚而自來矣，故曰「有不速之客三人來」也。陽貴陰賤，而上六既是陰柔，又居無位之地，三陽若來，必須恭敬之而終獲吉，故曰「敬之，終吉」。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
